/// One row of the `--release` version inventory: the version an Info.plist
/// claims. The artifact root itself is inventoried as `.`, followed by one
/// entry per nested component (under the same definition `--components`
/// uses); deeper-nested packages are not inspected. Fields are blank when
/// the declaration is absent or cannot be read, rather than dropping the row.
public struct ReleaseVersionEntry: Codable, Equatable, Sendable {
    /// `.` for the artifact root, otherwise the component path relative to it.
    public let path: String
    /// Raw `CFBundleShortVersionString` value; `""` when absent/unreadable.
    public let marketingVersion: String
    /// Raw `CFBundleVersion` value; `""` when absent/unreadable.
    public let buildVersion: String

    public init(path: String, marketingVersion: String, buildVersion: String) {
        self.path = path
        self.marketingVersion = marketingVersion
        self.buildVersion = buildVersion
    }

    private enum CodingKeys: String, CodingKey {
        case path
        case marketingVersion = "CFBundleShortVersionString"
        case buildVersion = "CFBundleVersion"
    }
}

/// One component whose build number trails the highest comparable build
/// number. Comparability requires the same number of dot-separated segments;
/// `referenceBuild` is the value this entry lags behind.
public struct ReleaseVersionLag: Codable, Equatable, Sendable {
    public let path: String
    /// The lagging entry's own raw build number.
    public let build: String
    /// Raw build number of the highest comparable entry.
    public let referenceBuild: String

    public init(path: String, build: String, referenceBuild: String) {
        self.path = path
        self.build = build
        self.referenceBuild = referenceBuild
    }
}

/// The `--release` build-number verdict, or `nil` when there is no component
/// or no comparable build number at all.
public struct ReleaseVersionConsistency: Codable, Equatable, Sendable {
    /// `true` when no participating build number trails another.
    public let consistent: Bool
    /// Every lagging entry, sorted by relative path. Empty when consistent.
    public let behind: [ReleaseVersionLag]

    public init(consistent: Bool, behind: [ReleaseVersionLag]) {
        self.consistent = consistent
        self.behind = behind
    }
}

public enum ReleaseResidualKind: String, Codable, Sendable {
    /// A `.swift` source file.
    case swift
    /// A directory whose name segment is exactly `Tests` (reported rolled up).
    case tests
    /// A `.dwarf` debug-symbol file.
    case dwarf
}

/// One leftover item that should not ship: a `.swift` source file, a `Tests`
/// directory (reported as a zero-byte entry with its subtree summarized via
/// `aggregatedBytes`/`aggregatedFileCount`, never expanded), or a `.dwarf`
/// debug-symbol file. Entries inside nested components and hidden entries are
/// never listed.
public struct ReleaseResidual: Codable, Equatable, Sendable {
    public let path: String
    public let kind: ReleaseResidualKind
    /// Bytes of the entry itself; always `0` for a `Tests` directory.
    public let bytes: UInt64
    /// Total bytes of regular files beneath a `Tests` directory; present only
    /// for `tests` entries.
    public let aggregatedBytes: UInt64?
    /// Number of regular files beneath a `Tests` directory; present only for
    /// `tests` entries.
    public let aggregatedFileCount: Int?

    public init(path: String,
                kind: ReleaseResidualKind,
                bytes: UInt64,
                aggregatedBytes: UInt64? = nil,
                aggregatedFileCount: Int? = nil) {
        self.path = path
        self.kind = kind
        self.bytes = bytes
        self.aggregatedBytes = aggregatedBytes
        self.aggregatedFileCount = aggregatedFileCount
    }
}

