/// Builds the version inventory: one row for the artifact root (`.`) and
/// one for each detected nested component. Only the component's own
/// top-level Info.plist is consulted — never one belonging to a deeper
/// nested package. Missing declarations or unreadable plists leave the
/// affected fields blank instead of failing the scan.
private func releaseVersionEntries(
    root: URL,
    rootIsDirectory: Bool,
    detectedComponents: [(url: URL, record: ArtifactComponent)],
    manager: FileManager
) throws -> [ReleaseVersionEntry] {
    var entries: [ReleaseVersionEntry] = []
    entries.append(
        versionEntry(
            path: ".",
            packageURL: root,
            kind: kind(for: root, isDirectory: rootIsDirectory),
            manager: manager
        )
    )
    for component in detectedComponents {
        entries.append(
            versionEntry(
                path: component.record.path,
                packageURL: component.url,
                kind: component.record.kind,
                manager: manager
            )
        )
    }
    return entries
