private func versionEntry(
    path: String,
    packageURL: URL,
    kind: ArtifactKind,
    manager: FileManager
) -> ReleaseVersionEntry {
    var marketing = ""
    var build = ""
    if let plistURL = infoPlistCandidates(for: packageURL, kind: kind, manager: manager).first {
        // A malformed or unreadable Info.plist is a blank declaration,
        // not an atomic scan failure: the inventory's job is to report
        // what the artifact claims, including the absence of a claim.
        if let data = try? Data(contentsOf: plistURL),
           let plist = try? PropertyListSerialization.propertyList(from: data, options: [], format: nil) as? [String: Any] {
            marketing = ArtifactScanner.plistString(plist["CFBundleShortVersionString"])
            build = ArtifactScanner.plistString(plist["CFBundleVersion"])
        }
    }
    return ReleaseVersionEntry(path: path, marketingVersion: marketing, buildVersion: build)
}

/// Conventional top-level Info.plist location for each package kind.
/// Frameworks historically keep theirs under `Versions/A/Resources`; the
/// short list is ordered so resolution is deterministic. Returns an empty
/// list for artifact files (`.pkg`/`.dmg`) and plain file roots, which
/// cannot carry an Info.plist.
private func infoPlistCandidates(for url: URL, kind: ArtifactKind, manager: FileManager) -> [URL] {
    let candidates: [URL]
    switch kind {
    case .application, .bundle:
        candidates = [url.appendingPathComponent("Contents/Info.plist")]
    case .framework:
        candidates = [
            url.appendingPathComponent("Versions/A/Resources/Info.plist"),
            url.appendingPathComponent("Versions/Current/Resources/Info.plist"),
            url.appendingPathComponent("Resources/Info.plist"),
        ]
    case .directory:
        candidates = [url.appendingPathComponent("Info.plist")]
    case .package, .diskImage, .file:
        candidates = []
    }
    return candidates.filter { manager.fileExists(atPath: $0.path) }
}

private static func plistString(_ value: Any?) -> String {
    switch value {
    case let string as String: string
    case let number as NSNumber: number.stringValue
    default: ""
    }
}

/// Build-number consistency. Only valid dotted-decimal build numbers
/// participate, and entries are compared only within groups sharing the
/// same segment count ("段数相同…逐段比较"). Each group's highest vector
/// is that group's reference; anything strictly below it lags. Ties for
/// the maximum are consistent. Returns `nil` when no component exists or
/// no participant carries a comparable build number.
private static func consistency(for entries: [ReleaseVersionEntry], hasComponents: Bool) -> ReleaseVersionConsistency? {
    guard hasComponents else { return nil }

    struct Build {
        let path: String
        let raw: String
        let segments: [UInt64]
    }

    let builds = entries.compactMap { entry -> Build? in
        guard let segments = parseBuildNumber(entry.buildVersion) else { return nil }
        return Build(path: entry.path, raw: entry.buildVersion, segments: segments)
    }
    guard !builds.isEmpty else { return nil }

    var behind: [ReleaseVersionLag] = []
    var groups: [Int: [Build]] = [:]
    for build in builds {
        groups[build.segments.count, default: []].append(build)
    }
    for group in groups.values {
        // Highest segment vector in the group, compared elementwise.
        let maxVector = group.map(\.segments).max { lhs, rhs in
            for (l, r) in zip(lhs, rhs) where l != r { return l < r }
            return false
        }!
        let leaders = group.filter { $0.segments == maxVector }
        // Reference value for lag reports: deterministic regardless of
        // enumeration order, even if numerically-equal maxima were written
        // with different raw spellings.
        let referenceRaw = leaders.map(\.raw).sorted().first!
        for build in group where build.segments != maxVector {
            behind.append(
                ReleaseVersionLag(path: build.path, build: build.raw, referenceBuild: referenceRaw)
            )
        }
    }
    behind.sort { lhs, rhs in
        if lhs.path == "." { return true }
        if rhs.path == "." { return false }
        return lhs.path < rhs.path
    }
    return ReleaseVersionConsistency(consistent: behind.isEmpty, behind: behind)
}

/// Parses a build number as dot-separated non-negative decimal integers,
/// or rejects it (`nil`) when any segment is empty, non-decimal, signed,
/// or too large. Empty strings are rejected.
private static func parseBuildNumber(_ raw: String) -> [UInt64]? {
    let parts = raw.split(separator: ".", omittingEmptySubsequences: false)
    guard !parts.isEmpty, raw.first != ".", raw.last != "." else { return nil }
    return try? parts.map { part in
        guard !part.isEmpty, part.allSatisfy({ $0.isASCII && $0.isNumber }) else {
            throw BuildParseError.invalid
        }
        guard let value = UInt64(part) else { throw BuildParseError.invalid }
        return value
    }
}

private enum BuildParseError: Error { case invalid }

/// Combines the plain file hits and the rolled-up `Tests` directories and
/// applies the residual ordering: bytes descending, then relative path
/// ascending — fully content-defined, never enumeration-order-dependent.
private static func sortedResiduals(files: [ReleaseResidual], tests: [TestsRollup]) -> [ReleaseResidual] {
    let testsEntries = tests.map { rollup in
        ReleaseResidual(
            path: rollup.path,
            kind: .tests,
            bytes: 0,
            aggregatedBytes: rollup.bytes,
            aggregatedFileCount: rollup.fileCount
        )
    }
    return (files + testsEntries).sorted { lhs, rhs in
        if lhs.bytes != rhs.bytes { return lhs.bytes > rhs.bytes }
        return lhs.path < rhs.path
    }
}

