import Foundation
import ReleaseLensCore

let arguments = Array(CommandLine.arguments.dropFirst())

func usage() -> Never {
    FileHandle.standardError.write(Data("Usage: releaselens scan <artifact-path> [--pretty] [--components]\n".utf8))
    exit(64)
}

guard arguments.count >= 2, arguments.first == "scan" else {
    usage()
}

var pretty = false
var includeComponents = false
for option in arguments.dropFirst(2) {
    switch option {
    case "--pretty": pretty = true
    case "--components": includeComponents = true
    default: usage()
    }
}

do {
    let summary = try ArtifactScanner().scan(URL(fileURLWithPath: arguments[1]), includeComponents: includeComponents)
    let encoder = JSONEncoder()
    encoder.outputFormatting = pretty ? [.prettyPrinted, .sortedKeys] : [.sortedKeys]
    FileHandle.standardOutput.write(try encoder.encode(summary))
    FileHandle.standardOutput.write(Data("\n".utf8))
} catch {
    FileHandle.standardError.write(Data("\(error.localizedDescription)\n".utf8))
    exit(1)
}

