private func infoPlistCandidates(for url: URL, kind: ArtifactKind, manager: FileManager) -> [URL] {
    let candidates: [URL]
    switch kind {
    case .application, .bundle:
        candidates = [url.appendingPathComponent("Contents/Info.plist")]
    case .framework:
